    correct: 2,
    explanation: 'Privacy by Design, introduced by Ann Cavoukian and now codified in GDPR Article 25 (data protection by design and by default), requires privacy controls to be architectural — built in from the start, not added as an afterthought. For AI: this means data minimisation in training sets, purpose limitation, differential privacy, federated learning, and privacy-preserving inference. AAISM treats PbD as a foundational AI privacy control.',
